644	/**
645	 * The list view needs comment and attachment counts per row. Two grouped
646	 * queries beat N+1 round trips, so the counts are folded in afterwards.
647	 */
648	export async function listIssuesWithRelations(
649	  input: IssueFilterInput,
650	): Promise<Page<IssueWithRelations>> {
651	  const db = getDb();
652	  const page = await listIssues(input);
653	  const ids = page.items.map((issue) => issue.id);
654	  if (ids.length === 0) {
655	    return { items: [], nextCursor: page.nextCursor, total: page.total };
656	  }
657	
658	  const commentCounts = db
659	    .select({ issueId: comments.issueId, value: count() })
660	    .from(comments)
661	    .where(
662	      and(
663	        orgPredicate(comments.orgId, input.orgId),
664	        inArray(comments.issueId, [...ids]),
665	        isNull(comments.archivedAt),
666	      ),
667	    )
668	    .groupBy(comments.issueId)
669	    .all();
670	
671	  const attachmentCounts = db
672	    .select({ issueId: attachments.issueId, value: count() })
673	    .from(attachments)
674	    .where(
675	      and(
676	        orgPredicate(attachments.orgId, input.orgId),
677	        inArray(attachments.issueId, [...ids]),
678	      ),
679	    )
680	    .groupBy(attachments.issueId)
681	    .all();
682	
683	  const labels = await listLabelsForIssues(input.orgId, ids);
684	  const commentsBy = new Map(commentCounts.map((r) => [r.issueId, r.value]));
685	  const attachmentsBy = new Map(
686	    attachmentCounts.map((r) => [r.issueId, r.value]),
687	  );
688	
689	  return {
690	    items: page.items.map((issue) => ({
691	      issue,
692	      labels: labels[issue.id] ?? [],
693	      commentCount: commentsBy.get(issue.id) ?? 0,
694	      attachmentCount: attachmentsBy.get(issue.id) ?? 0,
695	    })),
696	    nextCursor: page.nextCursor,
697	    total: page.total,
698	  };
699	}
