1	/**
2	 * The URL is the single source of truth for the issue list filter: a filtered
3	 * view has to be shareable and survive a reload, and the server component that
4	 * renders the page parses the very same query string. These two functions are
5	 * that codec, kept pure so both sides can use them.
6	 *
7	 * `assignee=none` is the sanctioned spelling of "unassigned" — `undefined`
8	 * means "don't filter on assignee at all", which is a different query.
9	 */
10	import type { LabelId, ProjectId, IsoTimestamp, UserId } from "@/types/common";
11	import {
12	  ISSUE_PRIORITIES,
13	  ISSUE_STATUSES,
14	  type IssueFilter,
15	  type IssuePriority,
16	  type IssueStatus,
17	} from "@/types/issue";
18	
19	export const UNASSIGNED_TOKEN = "none";
20	
21	export interface ReadableParams {
22	  get(name: string): string | null;
23	}
24	
25	function splitList(raw: string | null): readonly string[] {
26	  if (raw === null || raw.length === 0) return [];
27	  return raw
28	    .split(",")
29	    .map((part) => part.trim())
30	    .filter((part) => part.length > 0);
31	}
32	
33	export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
34	  const statuses = splitList(params.get("status")).filter(
35	    (value): value is IssueStatus =>
36	      ISSUE_STATUSES.includes(value as IssueStatus),
37	  );
38	  const priorities = splitList(params.get("priority")).filter(
39	    (value): value is IssuePriority =>
40	      ISSUE_PRIORITIES.includes(value as IssuePriority),
41	  );
42	  const labelIds = splitList(params.get("label")) as readonly LabelId[];
43	  const project = params.get("project");
44	  const assignee = params.get("assignee");
45	  const author = params.get("author");
46	  const query = params.get("q");
47	  const dueBefore = params.get("due_before");
48	
49	  const filter: IssueFilter = {
50	    ...(project !== null ? { projectId: project as ProjectId } : {}),
51	    ...(statuses.length > 0 ? { status: statuses } : {}),
52	    ...(priorities.length > 0 ? { priority: priorities } : {}),
53	    ...(assignee !== null
54	      ? {
55	          assigneeId:
56	            assignee === UNASSIGNED_TOKEN ? null : (assignee as UserId),
57	        }
58	      : {}),
59	    ...(author !== null ? { authorId: author as UserId } : {}),
60	    ...(labelIds.length > 0 ? { labelIds } : {}),
61	    ...(query !== null && query.length > 0 ? { query } : {}),
62	    ...(dueBefore !== null ? { dueBefore: dueBefore as IsoTimestamp } : {}),
63	    ...(params.get("archived") === "1" ? { includeArchived: true } : {}),
64	  };
65	
66	  return filter;
67	}
68	
69	/** Inverse of `parseIssueFilterParams`; omits every empty dimension so the
70	 *  canonical URL for "no filter" is the bare path. */
71	export function issueFilterToParams(
72	  filter: IssueFilter,
73	): Readonly<Record<string, string>> {
74	  const params: Record<string, string> = {};
75	  if (filter.projectId !== undefined) params.project = filter.projectId;
76	  if (filter.status !== undefined && filter.status.length > 0) {
77	    params.status = filter.status.join(",");
78	  }
79	  if (filter.priority !== undefined && filter.priority.length > 0) {
80	    params.priority = filter.priority.join(",");
81	  }
82	  if (filter.assigneeId !== undefined) {
83	    params.assignee = filter.assigneeId ?? UNASSIGNED_TOKEN;
84	  }
85	  if (filter.authorId !== undefined) params.author = filter.authorId;
86	  if (filter.labelIds !== undefined && filter.labelIds.length > 0) {
87	    params.label = filter.labelIds.join(",");
88	  }
89	  if (filter.query !== undefined && filter.query.length > 0) {
90	    params.q = filter.query;
91	  }
92	  if (filter.dueBefore !== undefined) params.due_before = filter.dueBefore;
93	  if (filter.includeArchived === true) params.archived = "1";
94	  return params;
95	}
96	
97	/** How many dimensions the user has narrowed on, for the "clear" affordance. */
98	export function activeFilterCount(filter: IssueFilter): number {
99	  return Object.keys(issueFilterToParams(filter)).length;
100	}
101	
102	export function issueFilterQueryString(filter: IssueFilter): string {
103	  const search = new URLSearchParams(issueFilterToParams(filter));
104	  const serialised = search.toString();
105	  return serialised.length > 0 ? `?${serialised}` : "";
106	}
107	"use client";
108	
109	/**
110	 * Reads and writes the issue filter through the URL search params.
111	 */
112	import { useCallback, useMemo } from "react";
113	import { usePathname, useRouter, useSearchParams } from "next/navigation";
114	import type { IssueFilter } from "@/types/issue";
115	import {
116	  issueFilterQueryString,
117	  parseIssueFilterParams,
118	} from "./issue-filter-params";
119	
120	export function useIssueFilters(): {
121	  filter: IssueFilter;
122	  setFilter: (filter: IssueFilter) => void;
123	  reset: () => void;
124	} {
125	  const router = useRouter();
126	  const pathname = usePathname();
127	  const searchParams = useSearchParams();
128	
129	  const filter = useMemo(
130	    () => parseIssueFilterParams(searchParams),
131	    [searchParams],
132	  );
133	
134	  const setFilter = useCallback(
135	    (next: IssueFilter) => {
136	      // Changing a filter always returns to page 1; keeping the old cursor
137	      // would show an empty page for a narrower result set.
138	      router.replace(`${pathname}${issueFilterQueryString(next)}`, {
139	        scroll: false,
140	      });
141	    },
142	    [router, pathname],
143	  );
144	
145	  const reset = useCallback(() => {
146	    router.replace(pathname, { scroll: false });
147	  }, [router, pathname]);
148	
149	  return { filter, setFilter, reset };
150	}
