561	/** Builds the shared predicate list behind `listIssues` and its count. */
562	function issueFilters(input: IssueFilterInput): readonly SQL[] {
563	  const scope: ArchiveScope = shouldFilterArchived(input)
564	    ? {}
565	    : { includeArchived: true };
566	
567	  return compact(
568	    orgPredicate(issues.orgId, input.orgId),
569	    livePredicate(issues.archivedAt, scope),
570	    input.projectId === undefined
571	      ? undefined
572	      : eq(issues.projectId, input.projectId),
573	    input.status === undefined || input.status.length === 0
574	      ? undefined
575	      : inArray(issues.status, [...input.status]),
576	    input.priority === undefined || input.priority.length === 0
577	      ? undefined
578	      : inArray(issues.priority, [...input.priority]),
579	    // `null` and `undefined` both arrive from the "Anyone" option of the
580	    // filter bar, so neither narrows the list.
581	    input.assigneeId ? eq(issues.assigneeId, input.assigneeId) : undefined,
582	    input.authorId === undefined
583	      ? undefined
584	      : eq(issues.authorId, input.authorId),
585	    input.dueBefore === undefined ? undefined : lt(issues.dueAt, input.dueBefore),
586	    input.query === undefined
587	      ? undefined
588	      : or(
589	          like(issues.title, `%${input.query}%`),
590	          like(issues.description, `%${input.query}%`),
591	        ),
592	    input.labelIds === undefined || input.labelIds.length === 0
593	      ? undefined
594	      : inArray(
595	          issues.id,
596	          getDb()
597	            .select({ id: issueLabels.issueId })
598	            .from(issueLabels)
599	            .where(
600	              and(
601	                orgPredicate(issueLabels.orgId, input.orgId),
602	                inArray(issueLabels.labelId, [...input.labelIds]),
603	              ),
604	            ),
605	        ),
606	  );
607	}
