609	export async function listIssues(
610	  input: IssueFilterInput,
611	): Promise<Page<Issue>> {
612	  const db = getDb();
613	  const filters = issueFilters(input);
614	  const sort = { sortColumn: issues.createdAt, idColumn: issues.id };
615	
616	  const total = db
617	    .select({ value: count() })
618	    .from(issues)
619	    .where(and(...filters))
620	    .get();
621	
622	  const rows = db
623	    .select()
624	    .from(issues)
625	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
626	    .orderBy(desc(issues.createdAt), desc(issues.id))
627	    .limit(probeLimit(input.limit))
628	    .all();
629	
630	  const labels = await listLabelsForIssues(
631	    input.orgId,
632	    rows.map((row) => row.id as IssueId),
633	  );
634	
635	  return toPage(
636	    rows,
637	    input.limit,
638	    total?.value ?? 0,
639	    (row) => toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
640	    (row) => ({ id: row.id, sortValue: row.createdAt }),
641	  );
642	}
