1032	/**
1033	 * Creates an issue after four gates: tenant scope, the `issue:create`
1034	 * permission, a live parent project and the plan's per-project issue quota.
1035	 * Only then is a number allocated and `issue.created` published — everything
1036	 * reactive (notifications, search, webhooks, the audit log) hangs off that.
1037	 */
1038	export async function createIssue(
1039	  actor: Actor,
1040	  input: CreateIssueInput,
1041	): Promise<Issue> {
1042	  assertOrgScope(actor, input.orgId);
1043	
1044	  const project = requireFound(
1045	    await projectRepo.findProjectById(input.orgId, input.projectId),
1046	    "Project",
1047	    input.projectId,
1048	  );
1049	  assertNotArchived("Project", project.id, project);
1050	  assertCan(actor, "issue:create", projectResource(project));
1051	
1052	  const org = requireFound(
1053	    await orgRepo.findOrgById(input.orgId),
1054	    "Organization",
1055	    input.orgId,
1056	  );
1057	  const used = await issueRepo.countIssues(input.orgId, input.projectId);
1058	  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
1059	    throw new Error(
1060	      `Plan ${org.plan} allows no more issues in project ${project.key}`,
1061	    );
1062	  }
1063	
1064	  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
1065	  const issue = await issueRepo.insertIssue(input, actor.userId, number);
1066	
1067	  await emit("issue.created", {
1068	    ...actorEnvelope(actor),
1069	    issueId: issue.id,
1070	    projectId: issue.projectId,
1071	    title: issue.title,
1072	    assigneeId: issue.assigneeId,
1073	    priority: issue.priority,
1074	  });
1075	
1076	  return issue;
1077	}
