1083	  assertOrgScope(actor, input.orgId);
1084	
1085	  const before = requireFound(
1086	    await issueRepo.findIssueById(input.orgId, input.issueId),
1087	    "Issue",
1088	    input.issueId,
1089	  );
1090	  assertCan(actor, "issue:update", issueResource(before));
1091	  assertNotArchived("Issue", before.id, before);
1092	
1093	  const after = await issueRepo.updateIssue(input);
1094	
1095	  await emit("issue.updated", {
1096	    ...actorEnvelope(actor),
1097	    issueId: after.id,
1098	    projectId: after.projectId,
1099	    changedFields: Object.keys(input).filter(
1100	      (key) => key !== "orgId" && key !== "issueId",
1101	    ),
1102	  });
1103	
1104	  return after;
1105	}
