1108	export async function changeIssueStatus(
1109	  actor: Actor,
1110	  input: ChangeIssueStatusInput,
1111	): Promise<Issue> {
1112	  assertOrgScope(actor, input.orgId);
1113	
1114	  const before = requireFound(
1115	    await issueRepo.findIssueById(input.orgId, input.issueId),
1116	    "Issue",
1117	    input.issueId,
1118	  );
1119	  assertCan(actor, "issue:update", issueResource(before));
1120	  assertNotArchived("Issue", before.id, before);
1121	
1122	  if (before.status === input.status) return before;
1123	
1124	  const after = await issueRepo.setIssueStatus(
1125	    input.orgId,
1126	    input.issueId,
1127	    input.status,
1128	  );
1129	
1130	  await emit("issue.status_changed", {
1131	    ...actorEnvelope(actor),
1132	    issueId: after.id,
1133	    projectId: after.projectId,
