export function readableSearchParams(
  search: Readonly<Record<string, string | readonly string[] | undefined>>,
): ReadableParams {
  return {
    get(name) {
      const value = Object.prototype.hasOwnProperty.call(search, name)
        ? search[name]
        : undefined;
      if (value === undefined) return null;
      return typeof value === "string" ? value : value.join(",");
