/** All-of: the issue must carry every one of `labelIds`. */
function labelsPredicate(orgId: OrgId, labelIds: readonly LabelId[]): SQL {
  const wanted = [...new Set(labelIds)];
  return inArray(
    issues.id,
    getDb()
      .select({ id: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.labelId, wanted),
